  ui_story_5008_50080101_58_dialog_content = "Maaf, Dove. Tapi, memang begitulah tugas kalian.",
  ui_story_5008_50080101_59_dialog_content = "PlayerName dan yang lain sedang berjuang untuk menyingkirkan para Eclipsite agar kita bisa mengantarkan surat-surat yang terlambat itu kemari secepatnya.",
