  ui_story_5008_50080101_70_dialog_content = "Nah, kalau dilihat dari situasinya... Ayo kita bersihkan tempat ini dulu, lalu periksa setiap peralatannya.",
  ui_story_5008_50080101_71_dialog_content = "Baiklah. Kau sudah siap, Tweety?",
  ui_story_5008_50080101_72_dialog_content = "Hmm! Aku akan bewusaha sebaik mungkin!",
  ui_story_5008_50080101_73_dialog_content = "Wahai alam, maafkan kelancanganku ini.",
  ui_story_5008_50080101_74_dialog_content = "Untuk memastikan bahwa surat-surat yang belum terkirim ke Eraveil itu sampai kepada penerimanya...",
  ui_story_5008_50080101_75_dialog_content = "Mohon maafkan kami yang terpaksa melakukan pembersihan... Aku berjanji kau akan terlahir kembali di tempat lain.",
  ui_story_5008_50080101_76_dialog_content = "Wow! Aku sudah tidak sabaw wagi mewihat hasiwnya!",
  ui_story_5008_50080101_77_dialog_content = "Coo... Coo, coo...",
  ui_story_5008_50080201_1_dialog_content = "Fiuh! Akhiwnya, papan-papan ini sewesai kupewbaiki juga!",
  ui_story_5008_50080201_2_dialog_content = "Eh, aku menemukan sesuatu saat bewsih-bewsih tadi—sebuah wak suwat!",
  ui_story_5008_50080201_3_dialog_content = "Kalau dilihat dari desainnya, sepertinya ini buatan Illumina...",
  ui_story_5008_50080201_4_dialog_content = "Ya! Wak suwat di Northwand juga tampak sepewti ini!",
  ui_story_5008_50080201_5_dialog_content = "Nah, berarti di mana pun lokasinya, fungsi kantor pos tetaplah sama.",
  ui_story_5008_50080201_6_dialog_content = "Dengan bertukar surat, orang-orang di seluruh dunia bisa saling mendekatkan jarak.",
  ui_story_5008_50080201_7_dialog_content = "Ya! Bewawti pekewjaan kita sangat penting!",
  ui_story_5008_50080201_8_dialog_content = "Kadang aku malah berpikir bahwa itu terlalu penting!",
  ui_story_5008_50080201_9_dialog_content = "Kalau saja rak-rak di Illumina sama kosongnya dengan yang di sini...",
  ui_story_5008_50080201_10_dialog_content = "Sekarang tak ada apa-apa di tempat ini karena kantor posnya hancur.",
  ui_story_5008_50080201_11_dialog_content = "Karena tak ada tempat berpijak di sini, kurir kita tak bisa mengantarkan surat apa pun.",
  ui_story_5008_50080201_12_dialog_content = "Wah, wupanya begitu, ya?",
  ui_story_5008_50080201_13_dialog_content = "Bolehkah aku bekerja di sini?",
  ui_story_5008_50080201_14_dialog_content = "Mungkin kau tak akan mau bekerja di sini setelah kita selesai memperbaiki kantor pos ini, Dove.",
  ui_story_5008_50080201_15_dialog_content = "Coo? Kenapa?",
  ui_story_5008_50080201_16_dialog_content = "Karena jumlah surat yang harus dikirim ke Eraveil dari berbagai tempat di kontinen ini tidak terhitung banyaknya.",
  ui_story_5008_50080201_17_dialog_content = "Nah, aku yakin setelah beroperasi kembali, kantor ini akan kebanjiran surat lagi.",
  ui_story_5008_50080201_18_dialog_content = "Wah, sewu juga, ya!",
  ui_story_5008_50080201_19_dialog_content = "Coo... Jadi, semua surat itu tidak pernah terkirim... Aku tidak percaya ada alasan yang lebih rumit daripada kurir yang tidak mau bekerja.",
  ui_story_5008_50080201_20_dialog_content = "Seberapa pun dekat atau jauh jaraknya, orang-orang bisa merasa lebih dekat dengan bantuan Courier Union.",
  ui_story_5008_50080201_21_dialog_content = "Jadi, itu sebabnya kita kemari.",
  ui_story_5008_50080201_22_dialog_content = "Kuharap kita bisa segera membuka kembali rute surat melalui Eraveil.",
  ui_story_5008_50080201_23_dialog_content = "Tentu saja bisa!",
  ui_story_5008_50080301_1_dialog_content = "Konternya saja sudah hampir roboh... Coo...",
  ui_story_5008_50080301_2_dialog_content = "Wihat! Tidak sepawah itu, kok—catnya cuma tewkewupas!",
  ui_story_5008_50080301_3_dialog_content = "Hmm, sepewtinya bagian wuawnya hiwang... Jadi kewihatan powos begini!",
  ui_story_5008_50080301_4_dialog_content = "Lihat, ada lambang Courier Union di sini.",
  ui_story_5008_50080301_5_dialog_content = "Ayo kita pastikan apakah benda ini masih bisa digunakan.",
