  ui_story_5008_50080301_8_dialog_content = "Snowball Surge!",
  ui_story_5008_50080301_9_dialog_content = "Coo!",
  ui_story_5008_50080301_10_dialog_content = "Nah, wihat, 'kan? Sekawang waci meja kasiwnya sudah tewbuka!",
  ui_story_5008_50080301_11_dialog_content = "Meski lacinya terbuka, seluruh isinya jadi basah! Coo!",
  ui_story_5008_50080301_12_dialog_content = "Apa sih isinya? Uang Caewestite, ya?",
  ui_story_5008_50080301_13_dialog_content = "Bukan...",
  ui_story_5008_50080301_14_dialog_content = "Wow! Wupanya Nightium!",
  ui_story_5008_50080301_15_dialog_content = "Biaw kuwihat!",
  ui_story_5008_50080301_16_dialog_content = "Tweety, jangan lupa memberikannya padaku setelah kamu selesai, ya.",
