  ui_story_5008_50080301_18_dialog_content = "Tentu saja! Couwier Union memang yang tewbaik!",
  ui_story_5008_50080301_19_dialog_content = "Dulu, bangsa Caelestite membayar kerja keras kita dengan ini.",
