  ui_story_5008_50080301_31_dialog_content = "Hmm... Sebaiknya lain kali kalian memilih kudapan dengan lebih hati-hati...",
  ui_story_5008_50080401_1_dialog_content = "Nawoxel! Dove! Ada patung bundaw di sini!",
  ui_story_5008_50080401_2_dialog_content = "Kelihatannya tidak bundar sempurna, ya?",
  ui_story_5008_50080401_3_dialog_content = "Patung ini kelihatannya punya ciri khas Eraveilian...",
  ui_story_5008_50080401_4_dialog_content = "Ciri khas Eraveilian... Coo?",
