  ui_story_5008_50080401_8_dialog_content = "Kok meweka memasang patung kuwiw?",
  ui_story_5008_50080401_9_dialog_content = "Untuk mengenang kurir-kurir hebat di Union.",
  ui_story_5008_50080401_10_dialog_content = "Wow... Meweka pasti benaw-benaw sudah bekewja kewas, ya!",
