  ui_story_5008_50080401_14_dialog_content = "Nawoxel, kapan aku bisa setinggi kamu, ya?",
  ui_story_5008_50080401_15_dialog_content = "Kau ini masih kecil, Tweety. Kalau sudah besar nanti, kau pasti akan lebih tinggi.",
  ui_story_5008_50080401_16_dialog_content = "Tapi, kok Dove tetap pendek sekawi wawau sudah besaw?",
  ui_story_5008_50080401_17_dialog_content = "Dove...?",
  ui_story_5008_50080401_18_dialog_content = "Enak sekali... bersandar pada meja resepsionis ini...",
