  ui_story_5008_50080401_20_dialog_content = "Bangun, Dove! Pekewjaan kita masih banyak, nih!",
  ui_story_5008_50080401_21_dialog_content = "Jama kerja maksimalku... sudah terlampaui...",
  ui_story_5008_50080401_22_dialog_content = "Biarkan aku jadi patung... dan berbaring dulu...",
  ui_story_5008_50080401_23_dialog_content = "Lima menit saja... tidak apa-apa...",
