  ui_story_5008_50080401_25_dialog_content = "Snowball Surge!",
  ui_story_5008_50080401_26_dialog_content = "Coo! Apa ini yang di kerah bajuku? Dingin sekali!",
  ui_story_5008_50080501_1_dialog_content = "Aku bewum pewnah wihat yang sepewti ini sebewumnya...",
  ui_story_5008_50080501_2_dialog_content = "Eh, ini kok kewihatan sepewti wintasan yang wusak, ya?",
  ui_story_5008_50080501_3_dialog_content = "Ada sabuk konveyownya, nih!",
  ui_story_5008_50080501_4_dialog_content = "Coo, coo? Sabuk konveyor? Benda ini dipakai agar kita tidak perlu mengangkat-angkat barang, ya?",
  ui_story_5008_50080501_5_dialog_content = "Sepertinya ini sistem transportasi kargo unik yang digunakan kantor pos Caelestite.",
  ui_story_5008_50080501_6_dialog_content = "Entah bagaimana cara kerjanya, dan kenapa dipasang di langit-langit...",
