  ui_story_5008_50080501_8_dialog_content = "Tentu saja, Tweety. Ada banyak hal yang tidak kuketahui.",
  ui_story_5008_50080501_9_dialog_content = "Bowehkah aku tanya sesuatu yang pasti kamu ketahui?",
  ui_story_5008_50080501_10_dialog_content = "Kamu ini sepewti ewf kawena sewawu memakai baju hijau!",
  ui_story_5008_50080501_11_dialog_content = "Kawau kuwawnai sayapku jadi hijau, apa aku juga akan kewihatan sepewti ewf?",
  ui_story_5008_50080501_12_dialog_content = "Tentu saja tidak!",
  ui_story_5008_50080501_13_dialog_content = "Oh, iya! Dove 'kan juga pakai baju hijau!",
  ui_story_5008_50080501_14_dialog_content = "Aneh, deh... Kawian sama-sama pakai baju hijau, tapi kenapa Dove tetap kewihatan sepewti mewpati biasa, ya?",
  ui_story_5008_50080501_15_dialog_content = "Coo...?",
  ui_story_5008_50080501_16_dialog_content = "Orang bodoh sepertimu memang tak ada tandingannya!",
  ui_story_5008_50080501_17_dialog_content = "Tapi, aku sudah bekewja dengan sangat kewas!",
  ui_story_5008_50080501_18_dialog_content = "Kau ini masih kecil, jadi tidak paham betapa sulitnya pekerjaan itu...",
  ui_story_5008_50080501_19_dialog_content = "Sebenarnya, aku penasaran... Kok kamu bisa bekerja padahal masih sangat polos begini?",
  ui_story_5008_50080501_20_dialog_content = "Tunggu... Jangan-jangan kantor cabang Northland memberikan bonus besar kepada kurir berdasarkan kinerjanya?",
  ui_story_5008_50080501_21_dialog_content = "Misalnya... liburan berbayar selama setahun?",
  ui_story_5008_50080501_22_dialog_content = "Tidak! Kami punya jatah wibuwan, tapi cuma sebentaw!",
  ui_story_5008_50080501_23_dialog_content = "Tapi, mau ada hadiah atau tidak, menuwutku kita hawus sewawu bekewja kewas!",
  ui_story_5008_50080501_24_dialog_content = "Nah, satu hal yang pasti—Kepala Illumina Vivian pasti akan menghargai etos kerja Anda!",
  ui_story_5008_50080501_25_dialog_content = "Kau pernah mempertimbangkan pindah ke kantor cabang lain? Coo, coo?",
  ui_story_5008_50080601_1_dialog_content = "Coo... Akhirnya, selesai juga aku membersihkan lantainya...",
  ui_story_5008_50080601_2_dialog_content = "Lantainya hampir seluas keseluruhan Illumina...",
  ui_story_5008_50080601_3_dialog_content = "Jangan mewebih-webihkan begitu, deh, Dove!",
  ui_story_5008_50080601_4_dialog_content = "Sttt! Naroxel datang!",
  ui_story_5008_50080601_5_dialog_content = "Tweety, coba lempari aku dengan bola salju, ya?",
  ui_story_5008_50080601_6_dialog_content = "(Lalu aku mau pura-pura pingsan di tanah...)",
  ui_story_5008_50080601_7_dialog_content = "Dasaw aneh! Tapi, baikwah. Snowball Sur—",
  ui_story_5008_50080601_8_dialog_content = "Coo! Kubilang bola saju! Satu saja sudah cukup!",
  ui_story_5008_50080601_9_dialog_content = "Eh! Nawoxel! Kamu kembawi!",
  ui_story_5008_50080601_10_dialog_content = "Dove bawu saja memintaku mewempawinya dengan bowa sawju! Mau ikut main?",
  ui_story_5008_50080601_11_dialog_content = "Oh...? Dove?",
  ui_story_5008_50080601_12_dialog_content = "Saya tidak menyangka bahwa Anda masih memiliki sisa kekuatan untuk pertarungan salju.",
  ui_story_5008_50080601_13_dialog_content = "Coo, coo, coo!",
  ui_story_5008_50080601_14_dialog_content = "A-aku jadi demam gara-gara bekerja terus, jadi kuminta Tweety melempariku dengan bola salju untuk meredakannya!",
  ui_story_5008_50080601_15_dialog_content = "Hmm... Sini, coba kuraba dahimu.",
  ui_story_5008_50080601_16_dialog_content = "Suhu badanmu kelihatannya normal, kok.",
  ui_story_5008_50080601_17_dialog_content = "S-sepertinya mataku belekan... Mata kiriku terus berair, warnanya merah, dan bengkak! Coo...",
  ui_story_5008_50080601_18_dialog_content = "Barusan aku melihatmu menggosok-gosok mata dengan keras, tapi aku tidak melihatnya berair.",
  ui_story_5008_50080601_19_dialog_content = "Coo... Sepertinya tempat ini jadi sarang kutu... Rasanya badanku gatal-gatal...",
  ui_story_5008_50080601_20_dialog_content = "A-aku harus... Coo, coo... mengajukan permohonan cuti sakit!",
  ui_story_5008_50080601_21_dialog_content = "Kau menjambak rambutmu... Memangnya tidak sakit?",
  ui_story_5008_50080601_22_dialog_content = "Dove, sebagai anggota Courier Union, kita harus mematuhi peraturan kurir.",
  ui_story_5008_50080601_23_dialog_content = "Kita harus menepati janji.",
  ui_story_5008_50080601_24_dialog_content = "Aku tahu betul kau sangat suka tidur, tapi tugas tetap harus dilaksanakan.",
  ui_story_5008_50080601_25_dialog_content = "Jadi... aku terpaksa menolak permohonanmu.",
  ui_story_5008_50080601_26_dialog_content = "Setelah tugas kita selesai, aku akan membantumu mengajukan permohonan cuti ke kantor cabang Illumina. Bagaimana?",
  ui_story_5008_50080601_27_dialog_content = "Coo, coo, coo... Baiklah...",
  ui_story_5008_50080701_1_dialog_content = "Kontainer apa ini? Kok kelihatannya tidak asing.",
  ui_story_5008_50080701_2_dialog_content = "Kira-kira apa isinya, ya? Benda ini tak bisa dibawa, tapi juga tak ada gunanya kalau ditinggal di sini...",
  ui_story_5008_50080701_3_dialog_content = "*Tok, tok* Rasanya cukup rapuh. Sepertinya tidak cukup stabil untuk kupakai tidur! Coo, coo!",
  ui_story_5008_50080701_4_dialog_content = "Dove! Ini 'kan vas!",
  ui_story_5008_50080701_5_dialog_content = "Kok bisa-bisanya kamu tidak tahu vas, sih? Bukannya kamu suka main-main dengan bunga saat di Iwumina?",
  ui_story_5008_50080701_6_dialog_content = "Main-main dengan bunga? Oh, maksudmu... merangkai bunga, ya? Menanam pohon?",
  ui_story_5008_50080701_7_dialog_content = "Oh, iya, benaw! Mewangkai bunga!",
  ui_story_5008_50080701_8_dialog_content = "Merangkai bunga? Sepertinya aku pernah lihat di buku.",
  ui_story_5008_50080701_9_dialog_content = "Aku hanya lihat vas kecil... Belum pernah lihat yang sebesar ini.",
  ui_story_5008_50080701_10_dialog_content = "Kewihatannya wawna vas ini miwip dengan wawna ikat kepawa PlayerName!",
  ui_story_5008_50080701_11_dialog_content = "Pola warna dan gayanya khas Eraveil.",
  ui_story_5008_50080701_12_dialog_content = "Coo... Vas ini kelihatan sangat familier. Aku yakin pernah melihatnya di suatu tempat sebelumnya.",
  ui_story_5008_50080701_13_dialog_content = "Hmm... Itu tembikaw, ya? Owang-owang Iwumina bisa membuat tembikaw?",
  ui_story_5008_50080701_14_dialog_content = "Coo! Kami tidak membuat tembikar...! Hoek!",
  ui_story_5008_50080701_15_dialog_content = "Ah! Benaw juga! Aku mewihatnya di kantow cabang Iwumina! Aku pewnah wihat vas-vas yang sepewti ini di kantow cabang Iwumina... Eh, maksudku kantow cabang Illumina!",
  ui_story_5008_50080701_16_dialog_content = "Karena jaringan transportasi di sini sudah tidak berfungsi, vas seperti ini hanya bisa dijumpai di Illumina.",
  ui_story_5008_50080701_17_dialog_content = "Vas itu pasti dikirim dari Eraveil ke Illumina.",
  ui_story_5008_50080701_18_dialog_content = "Vas itu ada di kantor cabang Illumina dalam waktu yang lama... Berarti, penerimanya tidak sempat mengambilnya.",
  ui_story_5008_50080701_19_dialog_content = "Atau mungkin saja mereka tak bisa mengambilnya.",
  ui_story_5008_50080701_20_dialog_content = "Coo, coo...",
  ui_story_5008_50080701_21_dialog_content = "Aku tidak menyadawinya... Vas itu sebenarnya adalah paket dari Eraveil...",
  ui_story_5008_50080701_22_dialog_content = "Bukan masalah. Kalau kembali nanti, kau bisa memberikan vas itu kepada si Caelestite. Biar dia menaruhnya di Colossus.",
  ui_story_5008_50080701_23_dialog_content = "Bukan hanya vas yang terbengkalai itu saja—ada lebih banyak paket di Umbraton yang menunggu dia tanda tangani.",
  ui_story_5008_50080701_24_dialog_content = "Para pemilik bingkisan itu mungkin saja tidak ada hubungannya dengan dia.",
  ui_story_5008_50080701_25_dialog_content = "Tapi, sepertinya hanya itu yang bisa kita lakukan.",
  ui_story_5008_50080701_26_dialog_content = "Karena hanya PlayerName yang tersisa.",
  ui_story_5008_50080701_27_dialog_content = "Coo...",
  ui_story_5008_50080701_28_dialog_content = "Kurasa dia punya banyak paket dan suwat untuk ditandatangani...",
  ui_story_5008_50080701_29_dialog_content = "Surat itu pasti sudah terbengkalai di depot Umbraton selama tujuh belas tahun. Saatnya dikembalikan kemari.",
  ui_story_5008_50080701_30_dialog_content = "Nawoxel, apa duwu Iwumina bewhubungan dengan Ewaveil?",
  ui_story_5008_50080701_31_dialog_content = "Tentu saja. Lagi pula, jaringan transportasi ini sudah ada sejak dulu.",
  ui_story_5008_50080701_32_dialog_content = "Tweety, kau tidak menyimak dengan baik saat sesi latihan, ya?",
  ui_story_5008_50080701_33_dialog_content = "Itu semua 'kan sudah diterangkan dalam buku panduan perkenalan Courier Union.",
  ui_story_5008_50080701_34_dialog_content = "Oh... Sepewtinya aku wupa...",
  ui_story_5008_50080701_35_dialog_content = "Kau ini memang konyow, Tweety.",
  ui_story_5008_50080701_36_dialog_content = "Dove, kok kamu jadi ikut-ikutan aksen Tweety, sih?",
  ui_story_5008_50080701_37_dialog_content = "<anim type=Shake>—Pffffft!</anim>",
  ui_story_5008_50080701_38_dialog_content = "Jangan bilang begitu, dong! Coo! Coo!",
  ui_story_5008_50080801_1_dialog_content = "Fiuh... Akhiwnya kita sewesai juga bewsih-bewsih!",
  ui_story_5008_50080801_2_dialog_content = "Meski semuanya masih bewum bewfungsi, setidaknya kita bisa mewihat sekewiwing tempat ini!",
  ui_story_5008_50080801_3_dialog_content = "Nah, karena tempat ini sudah dibersihkan...",
  ui_story_5008_50080801_4_dialog_content = "Tugas pertama sudah selesai... Naroxel, apa aku boleh pulang dan melapor?",
  ui_story_5008_50080801_5_dialog_content = "Kita bisa memperbaiki semuanya lain kali! Coo, coo!",
  ui_story_5008_50080801_6_dialog_content = "Dove, dalam permintaan staf bantuan itu, aku mengajukan permohonan agar—",
  ui_story_5008_50080801_7_dialog_content = "\"...Staf bantuan dipindahkan ke Eraveil Post Office hingga tempat itu kembali berfungsi\".",
  ui_story_5008_50080801_8_dialog_content = "Dove! Dove woboh ke wantai!",
  ui_story_5008_50080801_9_dialog_content = "Dove! Ayo bangun, dong!",
  ui_story_5008_50080801_10_dialog_content = "Coo! Aku tidak tidur! Aku ini pingsan, tahu?!",
  ui_story_5008_50080801_11_dialog_content = "Kau tidak capek bersih-bersih, Tweety?",
  ui_story_5008_50080801_12_dialog_content = "Kawau dipikiw-pikiw, aku agak capek, sih.",
  ui_story_5008_50080801_13_dialog_content = "Tapi, itu kawena aku bekewja tewus! Kawau kamu 'kan bewmawas-mawasan!",
  ui_story_5008_50080801_14_dialog_content = "Benar juga, sih.",
  ui_story_5008_50080801_15_dialog_content = "Coo, coo! Aku sudah bekerja lebih keras daripada saat di Illumina! Coo!",
  ui_story_5008_50080801_16_dialog_content = "Wah, pekerjaan kalian berdua bagus sekali.",
  ui_story_5008_50080801_17_dialog_content = "Sekarang kantor pos ini sudah hampir terlihat seperti sediakala... Tapi, ini saja belum cukup.",
  ui_story_5008_50080801_18_dialog_content = "PlayerName sedang melawan musuh di Eraveil. Mungkin semua berjalan lancar, tapi mungkin juga tidak...",
  ui_story_5008_50080801_19_dialog_content = "Yang jelas, kita tidak boleh buang-buang waktu. Kantor pos ini harus segera pulih secepatnya.",
  ui_story_5008_50080801_20_dialog_content = "Sejauh ini memang tidak mudah, tapi kabar baiknya adalah kita telah menyelesaikan semua tugas bersih-bersih yang membosankan ini.",
  ui_story_5008_50080801_21_dialog_content = "Sekarang kita bisa melanjutkan tugas perbaikan.",
  ui_story_5008_50080801_22_dialog_content = "Apa kau tidak penasaran bagaimana dulu Eraveil Post Office melayani bangsa Caelestite?",
  ui_story_5008_50080801_23_dialog_content = "Kau mau tahu jawaban yang sebenarnya, atau...?",
  ui_story_5008_50080801_24_dialog_content = "Aku tidak...",
  ui_story_5008_50080801_25_dialog_content = "Aku ingin tahu!",
  ui_story_5008_50080801_26_dialog_content = "Kalau begitu, ayo kita berusaha sebaik mungkin.",
  ui_story_5008_50080801_27_dialog_content = "Coba lihat keluar jendela. Perhatikan keindahan alami Eraveil.",
  ui_story_5008_50080801_28_dialog_content = "Alam secara tidak sengaja memberi kita kebahagiaan. Aku percaya itu.",
  ui_story_5008_50080801_29_dialog_content = "Hmm... Sepewtinya sekawang aku paham, Nawoxel!",
  ui_story_5008_50080801_30_dialog_content = "Ini kawena kita sudah bekewja dengan sangat kewas! Itu sebabnya kita bisa mewihat keindahan, 'kan?",
  ui_story_5008_50080801_31_dialog_content = "Sepertinya begitu.",
  ui_story_5008_50080801_32_dialog_content = "Ayo kita makan Union Snack dulu. Tugas berikutnya mungkin lebih berat.",
  ui_story_5008_50080801_33_dialog_content = "Wow! Baikwah!",
  ui_story_5008_50080801_34_dialog_content = "Mudah-mudahan aku tidak dapat rasa yang dulu itu, coo...",
  ui_story_5008_50080801_35_dialog_content = "Tidak, nanti kuberi rasa kesukaanmu.",
  ui_story_5008_50080801_36_dialog_content = "Dove—rasa Illumina Quilt.",
  ui_story_5008_50080801_37_dialog_content = "Tweety—rasa Cherry Blossom.",
  ui_story_5008_50080801_38_dialog_content = "Mmm... Wezat! Tewima kasih, Nawoxel!",
  ui_story_5008_50080801_39_dialog_content = "Dove pawing suka wasa Iwumina Quilt...?",
  ui_story_5008_50080801_40_dialog_content = "Jadi, awtinya setiap tempat punya kudapan wasa quilt spesiawnya sendiwi?",
  ui_story_5008_50080801_41_dialog_content = "Hmm... Aku pernah mencicipi rasa Rediesel Quilt dulu.",
  ui_story_5008_50080801_42_dialog_content = "Tidak kusarankan, sih.",
  ui_story_5008_50080801_43_dialog_content = "Coo... Aku jadi mengantuk setelah makan kudapan... Coo...",
  ui_story_5008_50080801_44_dialog_content = "Nah, karena Union Snack-nya sudah habis, ayo kita lanjutkan proyek ini.",
  ui_story_5008_50080801_45_dialog_content = "Ini juga sudah saatnya penambah semangat...",
  ui_story_5008_50080801_46_dialog_content = "Penambah semangat?",
  ui_story_5008_50080801_47_dialog_content = "Dove, Tweety! Kerja kalian luar biasa!",
  ui_story_5008_50080801_48_dialog_content = "Kalian berdua memang kurir yang hebat dan benar-benar menjadi teladan isi kredo Courier Union!",
  ui_story_5008_50080801_49_dialog_content = "Ayo kita ucapkan dengan lantang bersama-sama!",
  ui_story_5008_50080801_50_dialog_content = "Courier Union selalu berhasil mengantarkan surat!",
  ui_story_5008_50080801_51_dialog_content = "Bagus sekali.",
  ui_story_5008_50080801_52_dialog_content = "Nawoxel memuji hasil kerjaku!",
  ui_story_5008_50080801_53_dialog_content = "Ah! Coo! Permisi, Naroxel!",
  ui_story_5008_50080801_54_dialog_content = "Biasanya, rasa Union Snack tidak bisa ditebak dari bungkus luarnya saja...",
  ui_story_5008_50080801_55_dialog_content = "Lalu, bagaimana caranya kau bisa memilih rasa kesukaan kami tanpa membukanya dulu?",
  ui_story_5008_50080801_56_dialog_content = "Yah, itu mudah sekali.",
  ui_story_5008_50080801_57_dialog_content = "Kusuruh Olive dan Palm menjilat semua Union Snack dari tasku.",
  ui_story_5008_50080801_58_dialog_content = "Olive and Palm—dua burung kecil yang mengikutiku ke mana saja.",
  ui_story_5008_50080801_59_dialog_content = "Aku membuat lubang kecil pada bungkusnya dan meminta mereka menjilatnya. Lalu mereka memberitahuku rasanya.",
  ui_story_5008_50080801_60_dialog_content = "Setelah mereka menjilatnya, aku memilih rasa kesukaan kalian dan membungkusnya kembali.",
  ui_story_5008_50080801_61_dialog_content = "Coo!? Apa!?",
  ui_story_5008_50080801_62_dialog_content = "Pantas saja rasanya seperti ludah!",
  ui_story_5008_50080901_1_dialog_content = "Kok wampunya tak mau menyawa, sih?",
  ui_story_5008_50080901_2_dialog_content = "Padahaw aku sudah mempewbaikinya sepewti yang kuwakukan di Cwoud Bwossom Hotel!",
  ui_story_5008_50080901_3_dialog_content = "Mungkin lampu Eraveil berbeda dengan yang di Cloud Blossom Hotel...",
  ui_story_5008_50080901_4_dialog_content = "Hmm... Masuk akaw juga... Apa aku sawah mempewbaiki, ya?",
  ui_story_5008_50080901_5_dialog_content = "Tidak apa-apa, coo... Sini, biar kupakai teknik perbaikan Coo Coo Ca Choo yang sudah kupatenkan itu...",
  ui_story_5008_50080901_6_dialog_content = "<anim type=Shake><size=45>Jangan dipukuw! Jangan diwusak begitu!</size></anim>",
  ui_story_5008_50080901_7_dialog_content = "Kupikiw wampunya justwu jadi makin pawah setewah kamu wusak!",
  ui_story_5008_50080901_8_dialog_content = "Tidak ada tombol atau sakelar di luar lampu ini...",
  ui_story_5008_50080901_9_dialog_content = "Apa mungkin ini lampu yang otomatis menyala di jam-jam tertentu?",
  ui_story_5008_50080901_10_dialog_content = "Hmm... Ini waktunya menyawakan wampu, 'kan?",
  ui_story_5008_50080901_11_dialog_content = "Kuwasa begitu...",
  ui_story_5008_50080901_12_dialog_content = "Mungkin ada sambungan yang rusak di suatu tempat.",
  ui_story_5008_50080901_13_dialog_content = "Atau mungkin karena hal lain...",
  ui_story_5008_50080901_14_dialog_content = "Atau jangan-jangan sakelarnya tidak dikendalikan dengan sirkuit mekanis, tapi dengan suatu teknologi Caelestite?",
  ui_story_5008_50080901_15_dialog_content = "Kamu tidak yakin, Nawoxel?",
  ui_story_5008_50080901_16_dialog_content = "Maaf, aku sendiri merasa ragu.",
  ui_story_5008_50080901_17_dialog_content = "Kalian tangani saja dulu tugas yang lain. Biar kupikirkan cara menyalakan lampu ini...",
  ui_story_5008_50080901_18_dialog_content = "Nawoxel kewihatan tambah cantik kawau sedang bewpikiw kewas!",
  ui_story_5008_50080901_19_dialog_content = "Kalau kau ingin tambah dewasa, gunakan lebih banyak waktu untuk bekerja, bukannya melongo begitu, dong.",
  ui_story_5008_50080901_20_dialog_content = "Hah!? Justwu kamu ini yang hawus webih banyak bekewja, Dove!",
  ui_story_5008_50080901_21_dialog_content = "Coo, coo! Aku 'kan hanya memberitahumu cara menjadi dewasa.",
  ui_story_5008_50080901_22_dialog_content = "Oh... Masa, sih?",
  ui_story_5008_50080901_23_dialog_content = "Tapi, dawi tadi kamu hanya bewbawing saja di sana...",
  ui_story_5008_50080901_24_dialog_content = "Kamu juga hawus bewsikap webih dewasa, tahu?",
  ui_story_5008_50080901_25_dialog_content = "Hei! Aku sudah dewasa, kok!",
  ui_story_5008_50081001_1_dialog_content = "Aku sudah mempewbaiki kuwsi keciw ini!",
  ui_story_5008_50081001_2_dialog_content = "Apa mungkin pewanggan memesan di sini...?",
  ui_story_5008_50081001_3_dialog_content = "Dove, kamu mau jadi wesepsionis kantow pos di sini?",
  ui_story_5008_50081001_4_dialog_content = "Tentu saja. Halo, coo—ada yang bisa kubantu?",
  ui_story_5008_50081001_5_dialog_content = "Wah, cepat sekawi!",
  ui_story_5008_50081001_6_dialog_content = "Tapi, penampiwanmu tidak sepewti Caewestite...",
  ui_story_5008_50081001_7_dialog_content = "Kalau begitu... Seperti apa seharusnya resepsionis Caelestite itu?",
  ui_story_5008_50081001_8_dialog_content = "Yah... Kupikiw sehawusnya kamu ganti wawna ikat kepawamu jadi hitam dan putih duwu!",
  ui_story_5008_50081001_9_dialog_content = "Lalu, aku mulai memeriksa kantor pos seperti Navigator?",
  ui_story_5008_50081001_10_dialog_content = "Mungkin...",
  ui_story_5008_50081001_11_dialog_content = "Siap, Dove? Aku ingin memesan sesuatu!",
  ui_story_5008_50081001_12_dialog_content = "Apa yang ingin Anda kirim hari ini?",
  ui_story_5008_50081001_13_dialog_content = "Kiwim... Eh, aku ingin mengiwim dua bowa sawju keciw.",
  ui_story_5008_50081001_14_dialog_content = "Coo!? Bola salju Anda akan meleleh sebelum sampai tempat tujuan, Nona!",
  ui_story_5008_50081001_15_dialog_content = "Kita sedang bewmain, 'kan? Kamu hawus bewpuwa-puwa bahwa bowa sawju tak akan meweweh!",
  ui_story_5008_50081001_16_dialog_content = "Coo...",
  ui_story_5008_50081001_17_dialog_content = "Bola saju, ya? Baiklah, coo. Ke mana Anda ingin mengirimnya, Nona?",
  ui_story_5008_50081001_18_dialog_content = "Kiwim ke Wumopowis—untuk Nawoxel!",
  ui_story_5008_50081001_19_dialog_content = "Dengan begitu, Nawoxel akan wangsung tewingat padaku begitu dia wihat bowa sawju keciwku!",
  ui_story_5008_50081001_20_dialog_content = "Lumopolis, ya? Coo, biayanya... 100.000 Nightium!",
  ui_story_5008_50081001_21_dialog_content = "Apa!? Kok mahaw sekawi, sih!?",
  ui_story_5008_50081001_22_dialog_content = "Karena setiap mengantar surat ke Lumopolis, aku butuh banyak waktu dan tenaga untuk terbang melintasi kota!",
  ui_story_5008_50081001_23_dialog_content = "Ini semua sudah diperhitungkan dalam biaya, Nona.",
  ui_story_5008_50081001_24_dialog_content = "Huh! Kawau begitu, biaw kubewikan pada Nawoxel saja sendiwi!",
  ui_story_5008_50081001_25_dialog_content = "Hah? Ada apa ini?",
  ui_story_5008_50081001_26_dialog_content = "Nawoxel! Kamu kembawi! Aku punya bowa sawju keciw untukmu, who!",
  ui_story_5008_50081001_27_dialog_content = "Terima kasih, Tweety.",
  ui_story_5008_50081001_28_dialog_content = "Tapi, bola saljunya akan langsung mencair kalau kupegang.",
  ui_story_5008_50081001_29_dialog_content = "Tadi aku juga sudah bilang begitu, coo!",
  ui_story_5008_50081101_1_dialog_content = "Dong!",
  ui_story_5008_50081101_2_dialog_content = "Jamnya bewfungsi!",
  ui_story_5008_50081101_3_dialog_content = "Luar biasa, Tweety.",
  ui_story_5008_50081101_4_dialog_content = "Mungkinkah jam ini digunakan untuk melacak jam kerja mereka, ya...?",
  ui_story_5008_50081101_5_dialog_content = "Hmm... Kawau soaw itu, aku yakin meweka punya cawa yang webih canggih!",
  ui_story_5008_50081101_6_dialog_content = "Cara yang lebih canggih?",
  ui_story_5008_50081101_7_dialog_content = "Benaw! Semua Caewestite punya kemampuan psikis, 'kan?",
  ui_story_5008_50081101_8_dialog_content = "Mungkin meweka sudah tahu jam kewjanya hanya dengan sawing menatap!",
  ui_story_5008_50081101_9_dialog_content = "Itu terlalu berlebihan, ah!",
  ui_story_5008_50081101_10_dialog_content = "Jangan khawatiw, Dove!",
  ui_story_5008_50081101_11_dialog_content = "Kawau aku ini Caewestite, aku bakaw wangsung tahu bahwa kamu suka tiduw saat kewja.",
  ui_story_5008_50081101_12_dialog_content = "Tentu saja! Eh, sebentar... Maksudmu tidur, 'kan?",
  ui_story_5008_50081101_13_dialog_content = "Kalau Caelestite kira pekerjaanku hanya tidur saja...",
  ui_story_5008_50081101_14_dialog_content = "Aku bakal jadi pegawai teladan! Coo!",
  ui_story_5008_50081101_15_dialog_content = "Lalu aku pasti dapat kenaikan gaji!",
  ui_story_5008_50081101_16_dialog_content = "Tapi, tugasmu 'kan jadi kuwiw yang baik!",
  ui_story_5008_50081101_17_dialog_content = "Kenapa kamu tidak membiarkanku berandai-andai sebentar, sih?",
  ui_story_5008_50081101_18_dialog_content = "Semua orang harus punya impian!",
  ui_story_5008_50081101_19_dialog_content = "Dove, jamnya sudah diperbaiki.",
  ui_story_5008_50081101_20_dialog_content = "Coo? Aku tahu, kok. Fungsinya untuk menghitung mundur jam kerjaku...",
  ui_story_5008_50081101_21_dialog_content = "Nah, kuingatkan, ya... Karena sekarang kita bisa melihat waktu, kuperhatikan kau baru saja buang-buang waktu satu setengah jam.",
  ui_story_5008_50081101_22_dialog_content = "Coo! Hanya dua puluh enam menit, kok... Dua puluh enam menit!",
  ui_story_5008_50081101_23_dialog_content = "Suawa detik jamnya sangat bagus!",
  ui_story_5008_50081101_24_dialog_content = "Memang benar...",
  ui_story_5008_50081101_25_dialog_content = "Detiknya seolah-olah memberitahukan bahwa waktu yang terhenti begitu lama di Eraveil, kini berjalan kembali.",
  ui_story_5008_50081201_1_dialog_content = "Jadi, begitu cara kerjanya...",
  ui_story_5008_50081201_2_dialog_content = "Seperti yang kuharapkan dari kantor pos Eraveil.",
  ui_story_5008_50081201_3_dialog_content = "Coo! Sebaiknya kita catat cara kerja sistem ini!",
  ui_story_5008_50081201_4_dialog_content = "Ayo kita tawuh bebewapa bowa sawju keciw di ban bewjawan ini...",
  ui_story_5008_50081201_5_dialog_content = "Wow! Pawa Firefwie membawa bowa sawjunya ke atas!",
  ui_story_5008_50081201_6_dialog_content = "Apa mereka bisa mengangkat benda-benda berat, ya?",
  ui_story_5008_50081201_7_dialog_content = "Entahwah...",
  ui_story_5008_50081201_8_dialog_content = "Biaw kucoba—",
  ui_story_5008_50081201_9_dialog_content = "Coo, coo? Turun, Tweety!",
  ui_story_5008_50081201_10_dialog_content = "Jangan khawatiw, Dove!",
  ui_story_5008_50081201_11_dialog_content = "Kawau Firefwy membawaku kewuaw, aku 'kan bisa tewbang masuk wagi!",
  ui_story_5008_50081201_12_dialog_content = "Bukan itu yang aku khawatirkan!",
  ui_story_5008_50081201_13_dialog_content = "Aku khawatir aku takkan bisa berjalan lurus setelah dihujani banyak bola salju!",
  ui_story_5008_50081201_14_dialog_content = "Oh? Bowa sawju apa sih yang kamu maksud?",
  ui_story_5008_50081201_15_dialog_content = "Sebelum kau melompat ke sana, para Firefly membawa bola saljumu.",
  ui_story_5008_50081201_16_dialog_content = "Lalu kau melompat ke ban berjalan itu...",
  ui_story_5008_50081201_17_dialog_content = "Seluruh kantor pos jadi berguncang karena tidak kuat menahan berat tubuhmu...",
  ui_story_5008_50081201_18_dialog_content = "Lalu bola salju yang dibawa para Firefly itu menimpa kepalaku!",
  ui_story_5008_50081201_19_dialog_content = "Oh, maafkan aku, Dove! Aku tuwun, deh!",
  ui_story_5008_50081201_20_dialog_content = "Turun sekarang juga! Jangan melompat ke ban berjalan!",
  ui_story_5008_50081201_21_dialog_content = "Hiyah! Aku sudah tuwun, nih!",
  ui_story_5008_50081201_22_dialog_content = "Berapa sih beratmu?",
  ui_story_5008_50081201_23_dialog_content = "Hei...",
  ui_story_5008_50081201_24_dialog_content = "Wihat, Dove! Pawa Firefwy itu membawa bowa sawjunya kewuaw!",
  ui_story_5008_50081201_25_dialog_content = "Aku hanya membantumu memewiksa stwuktuw ban bewjawan Firefwy!",
  ui_story_5008_50081201_26_dialog_content = "Coo? Coba jelaskan padaku...",
  ui_story_5008_50081201_27_dialog_content = "Aku akan menggambar sistemnya dan memberikannya kepada Vice. Dia bisa membantuku membuat gambar mekanis yang lebih mendetail...",
  ui_story_5008_50081201_28_dialog_content = "Ini benar-benar sistem yang sangat canggih.",
  ui_story_5008_50081201_29_dialog_content = "Pekerjaan kurir-kurir kecil kita pasti akan jadi jauh lebih mudah kalau sistem ini bisa dipasang di kantor cabang yang lain.",
  ui_story_5008_50081201_30_dialog_content = "Selain itu, berarti peradaban bangsa Caelestite benar-benar lebih maju...",
  ui_story_5008_50081201_31_dialog_content = "Lagi pula, kantor pos ini beroperasi tujuh belas tahun yang lalu.",
  ui_story_5008_50081301_1_dialog_content = "Ini... Ini rak kartu pos!",
  ui_story_5008_50081301_2_dialog_content = "Wow! Aku mau wihat! Aku mau wihat!",
  ui_story_5008_50081301_3_dialog_content = "Apa kawtu pos ini dawi tujuh bewas tahun yang wawu?",
  ui_story_5008_50081301_4_dialog_content = "Mungkin, coo?",
  ui_story_5008_50081301_5_dialog_content = "Kulihat ada tanda Illumina di balik kartu pos ini.",
  ui_story_5008_50081301_6_dialog_content = "Pakaian mereka kelihatan agak berbeda dengan yang dipakai orang-orang Illumina zaman sekarang... Ini pasti seragam lama.",
  ui_story_5008_50081301_7_dialog_content = "Lihat—ada gambar Her Majesty di kartu pos Northland ini.",
  ui_story_5008_50081301_8_dialog_content = "Wah, ada kawtu pos Northwand juga?",
  ui_story_5008_50081301_9_dialog_content = "Aku mau cawi kawtu pos Cwoud Mountain, ah!",
  ui_story_5008_50081301_10_dialog_content = "Tentu saja ada kartu pos Northland, Tweety. Itu 'kan tempat yang terkenal...",
  ui_story_5008_50081301_11_dialog_content = "Tapi, sebelum bertemu denganmu, aku belum pernah dengar soal Cloud Mountain, sih.",
  ui_story_5008_50081301_12_dialog_content = "Dove, kamu pasti tak akan bisa bewteman dekat dengan Hiiwo...",
  ui_story_5008_50081301_13_dialog_content = "Yang benar saja, deh... Memangnya siapa sih yang mau berteman dekat dengan Legion Commander...?",
  ui_story_5008_50081301_14_dialog_content = "Bukankah kau malah akan jadi lebih mudah ketahuan saat bolos kerja?",
  ui_story_5008_50081301_15_dialog_content = "Kalau sedang bermalas-malasan, aku harus sembunyi setiap melihat Commander Hiiro!",
  ui_story_5008_50081301_16_dialog_content = "Dove, kamu memang benaw-benaw pemawas pwo!",
  ui_story_5008_50081301_17_dialog_content = "Sepewtinya kamu hawus sembunyi dawi banyak owang di kantow cabang Iwumina!",
  ui_story_5008_50081301_18_dialog_content = "Aku tidak yakin apakah bermalas-malasan itu bisa disebut kemampuan...",
  ui_story_5008_50081301_19_dialog_content = "Dove, aku berdiri di sini, lho.",
  ui_story_5008_50081301_20_dialog_content = "N-Naroxel... A-a-aku hanya bercanda, kok!",
  ui_story_5008_50081301_21_dialog_content = "Aduh, mana sih kawtu pos Cwoud Mountain-nya?",
  ui_story_5008_50081301_22_dialog_content = "Itu bisa jadi karena Cloud Mountain sangat tersembunyi. Bangsa Caelestite mungkin tidak tahu cara menghubungi kalian.",
  ui_story_5008_50081301_23_dialog_content = "Hmm... Mungkin kamu benaw!",
  ui_story_5008_50081301_24_dialog_content = "Tidak ada banyak kawtu pos Ewaveil di wak ini...",
  ui_story_5008_50081301_25_dialog_content = "Kalau ada kesempatan... kita bisa mencari pedagang di Umbraton dan memesan beberapa kartu pos Eraveil baru.",
  ui_story_5008_50081301_26_dialog_content = "Yang benaw, Nawoxel?",
  ui_story_5008_50081301_27_dialog_content = "Tentu saja. Lagi pula, Eraveil sekarang berbeda dengan Eraveil di masa lalu. Lihat saja kartu pos lama itu.",
  ui_story_5008_50081401_1_dialog_content = "Eh, benaw juga! Sekawang bantaw keciw ini jadi sangat wembut dan nyaman!",
  ui_story_5008_50081401_2_dialog_content = "Coo! Tweety, lihat itu...",
  ui_story_5008_50081401_3_dialog_content = "Wow! Nawoxel, Dove! Wihat! Ada anak kucing!",
  ui_story_5008_50081401_4_dialog_content = "Sini, Pus-pus!",
  ui_story_5008_50081401_5_dialog_content = "Pus-meong... Pus-meong?",
  ui_story_5008_50081401_6_dialog_content = "Pus-meong? Apa itu?",
  ui_story_5008_50081401_7_dialog_content = "Kan biasanya memang begitu cara orang memanggil kucing. Memang apa itu \"pus-pus\"?",
  ui_story_5008_50081401_8_dialog_content = "Hmm... Di Cwoud Mountain, kami memanggiwnya dengan \"pus-pus\".",
  ui_story_5008_50081401_9_dialog_content = "Bagaimana kawau kita sama-sama membewinya nama?",
  ui_story_5008_50081401_10_dialog_content = "Memberi nama itu sulit... Coba kamu dulu, deh.",
  ui_story_5008_50081401_11_dialog_content = "Aku tahu! Bagaimana kawau \"Cuddles\"?",
  ui_story_5008_50081401_12_dialog_content = "Kawena dia imut dan wembut sekawi!",
  ui_story_5008_50081401_13_dialog_content = "Aduh, biasa sekali kedengarannya... Ini kucing Eraveil, lho!",
  ui_story_5008_50081401_14_dialog_content = "Bagaimana kalau yang sedikit lebih unik... misalnya \"Era\"?",
  ui_story_5008_50081401_15_dialog_content = "Coba kamu pikir lagi, deh.",
  ui_story_5008_50081401_16_dialog_content = "Ah... Bagaimana kawau \"Snowball\"?",
  ui_story_5008_50081401_17_dialog_content = "Nama-nama yang kamu cari itu berdasarkan hal-hal yang kamu sukai, ya?",
  ui_story_5008_50081401_18_dialog_content = "Tapi, bentuknya memang sepewti bowa, 'kan?",
  ui_story_5008_50081401_19_dialog_content = "Bagaimana kalau \"Sleepy\"...?",
  ui_story_5008_50081401_20_dialog_content = "Kucing 'kan suka tidur...",
  ui_story_5008_50081401_21_dialog_content = "Iya, tapi bewum ada apa-apanya dibandingkan kamu, Dove!",
  ui_story_5008_50081401_22_dialog_content = "Aduh, ketahuan, deh.",
  ui_story_5008_50081401_23_dialog_content = "Yah, karena kucing selalu bersikap sangat dingin, kita beri saja dia nama...",
  ui_story_5008_50081401_24_dialog_content = "Coo-Coo.",
  ui_story_5008_50081401_25_dialog_content = "Kedengawannya tidak masuk akaw, Dove!",
  ui_story_5008_50081401_26_dialog_content = "Itu 'kan kucing, bukan mewpati!",
  ui_story_5008_50081401_27_dialog_content = "Heh! Kamu itu yang merpati! Dasar... merpati! Bukan... Kamu itu spesies baru—makhluk mini yang cerewet!",
  ui_story_5008_50081401_28_dialog_content = "Tadinya kupikir kalian terlalu tua untuk bertengkar seperti ini...",
  ui_story_5008_50081401_29_dialog_content = "Naroxel, Tweety duluan kok yang menyebutku merpati! Aku lebih dewasa dari dia!",
  ui_story_5008_50081401_30_dialog_content = "Tidak! Menuwutku kamu bewum kewihatan dewasa... tapi yang jewas kamu ini kewihatan mawas!",
  ui_story_5008_50081401_31_dialog_content = "Tweety, kamu ini masih kecil. Masih ada banyak hal yang belum kamu tahu.",
  ui_story_5008_50081401_32_dialog_content = "Sudah, sudah. Kalau kalian terus bertengkar seperti ini, nanti kucingnya ketakutan.",
  ui_story_5008_50081401_33_dialog_content = "Para kucing liar berhasil bertahan hidup di tempat yang berbahaya dan terpencil seperti ini...",
  ui_story_5008_50081401_34_dialog_content = "Kekuatan alam memang sebaiknya tidak diremehkan. Apa kita bisa menemukan teman-temannya atau hewan kecil lain di sekitar sini, ya?",
  ui_story_5008_50081401_35_dialog_content = "Nawoxel! Kenapa bukan kamu saja yang membewinya nama?",
  ui_story_5008_50081401_36_dialog_content = "Hmm... Aku tidak begitu pintar memberi nama.",
  ui_story_5008_50081401_37_dialog_content = "Tapi, nama dua buwungmu itu bagus sekawi!",
  ui_story_5008_50081401_38_dialog_content = "Terima kasih, Tweety.",
  ui_story_5008_50081401_39_dialog_content = "Tapi, tidak semua makhluk butuh nama. Lagi pula, nama hanyalah kode.",
  ui_story_5008_50081401_40_dialog_content = "Selama dia disayangi, \"pus-meong\" saja juga sudah jadi nama panggilan yang bagus, 'kan?",
  ui_story_5008_50081501_1_dialog_content = "Kalian berdua sudah bekerja dengan sangat keras.",
  ui_story_5008_50081501_2_dialog_content = "Eraveil Post Office kini sudah dalam keadaan baik.",
  ui_story_5008_50081501_3_dialog_content = "Bukan hanya tertata rapi, tapi juga sudah terasa seperti kantor sungguhan sekarang...",
  ui_story_5008_50081501_4_dialog_content = "Rak, jam, kartu pos...",
  ui_story_5008_50081501_5_dialog_content = "Sebagian besar adalah peralatan standar Courier Union...",
  ui_story_5008_50081501_6_dialog_content = "Tapi, tidak ada kucing di kantow cabang Iwumina!",
  ui_story_5008_50081501_7_dialog_content = "Coo, tapi kita 'kan punya Philyshy!",
  ui_story_5008_50081501_8_dialog_content = "Baiklah, Dove, Tweety.",
  ui_story_5008_50081501_9_dialog_content = "Misi kita tetap sama. Peralatan kantor pos harus sama.",
  ui_story_5008_50081501_10_dialog_content = "Terutama di sini...",
  ui_story_5008_50081501_11_dialog_content = "Kantor pos ini akan beroperasi sekali lagi setelah tujuh belas tahun bergeming.",
  ui_story_5008_50081501_12_dialog_content = "Nawoxel!",
  ui_story_5008_50081501_13_dialog_content = "Bisakah gunungan suwat dawi Umbwaton dikiwim kemawi sekawang?",
  ui_story_5008_50081501_14_dialog_content = "Yah... Itu tergantung persetujuan PlayerName.",
  ui_story_5008_50081501_15_dialog_content = "Setelah menandatanganinya, dia akan jadi penerima surat Eraveil.",
  ui_story_5008_50081501_16_dialog_content = "Kuharap semua baik-baik saja... dan dia bisa kembali kemari dengan selamat.",
  ui_story_5008_50081501_17_dialog_content = "Caelestite itu akan melihat Eraveil Post Office ini dalam keadaan pulih...",
  ui_story_5008_50081501_18_dialog_content = "Luar biasa! Coo!",
  ui_story_5008_50081501_19_dialog_content = "Naroxel... Sekarang sudah selesai semua, 'kan?",
  ui_story_5008_50081501_20_dialog_content = "Karena kita harus menunggu PlayerName kembali kemari, bolehkah aku tidur dulu?",
  ui_story_5008_50081501_21_dialog_content = "Akhiwnya, Dove punya awasan untuk tiduw!",
  ui_story_5008_50081501_22_dialog_content = "Eh, aku hampir lupa... Sebenarnya, hari ini adalah festival spesial untuk bangsa Caelestite—Windelion.",
  ui_story_5008_50081501_23_dialog_content = "Windewion...",
  ui_story_5008_50081501_A1_dialog_content = "PlayerName pewnah menyebut-nyebut soal Windewion, tapi aku masih tidak tahu festivaw yang sepewti apa itu!",
  ui_story_5008_50081501_24_dialog_content = "Pasti hanya PlayerName yang tahu detail dari festival itu.",
  ui_story_5008_50081501_25_dialog_content = "Tapi, pasti ada hiasan, makanan, dan acara kumpul-kumpul di festival itu.",
  ui_story_5008_50081501_26_dialog_content = "Meski kantor pos sudah berfungsi lagi... Tempat ini masih kelihatan sedikit kosong.",
  ui_story_5008_50081501_27_dialog_content = "Kantor pos ini sudah kembali beroperasi.",
  ui_story_5008_50081501_28_dialog_content = "Mungkin... kita bisa menghias tempat ini bersama-sama?",
  ui_story_5008_50081501_29_dialog_content = "Ayo!",
  ui_story_5008_50081501_30_dialog_content = "PlayerName sehawusnya akan tiba saat kita sudah sewesai menghias!",
  ui_story_5008_50081501_31_dialog_content = "Nanti dia pasti tewkejut saat mewihat dekowasi untuk festivaw!",
  ui_story_5008_50081501_32_dialog_content = "Iya, aku juga yakin begitu. Tapi, gaya dekorasi untuk Windelion itu seperti apa, ya?",
  ui_story_5008_50081501_33_dialog_content = "Ah, masa bodoh deh dengan gaya!",
  ui_story_5008_50081501_34_dialog_content = "Coo... Asalkan kita berhati-hati, dekorasinya pasti akan bagus.",
  ui_story_5008_50081501_35_dialog_content = "Wow! Dove bisa tahu soal hati-hati juga, ya?",
  ui_story_5008_50081501_36_dialog_content = "Yah, PlayerName pernah menyelamatkanku satu kali...",
  ui_story_5008_50081501_37_dialog_content = "Jadi, aku tak keberatan kalau harus menghias tempat ini untuknya.",
  ui_story_5008_50081501_38_dialog_content = "Ayo kita berusaha sebaik mungkin.",
  ui_story_5008_50081501_39_dialog_content = "Karena tidak tahu bagaimana keadaan mereka... kita hanya bisa mencoba sebaik mungkin untuk mengurus masalah ini sendiri.",
  ui_story_5008_50081501_40_dialog_content = "Tapi, tidak ada banyak benda yang bisa dijadikan dekowasi di sini...",
  ui_story_5008_50081501_41_dialog_content = "Hmm... Kami menghias kantow pos di Cwoud Mountain dengan bunga sakuwa. Kita pakai apa nih kawau di sini?",
  ui_story_5008_50081501_42_dialog_content = "Aku bisa menghubungi Union dan meminta kiriman material dekorasi secepatnya.",
  ui_story_5008_50081501_43_dialog_content = "Selain itu, aku juga sudah memahami teknologi Caelestite. Mungkin kita bisa menggunakannya untuk menghias tempat ini.",
  ui_story_5008_50081501_44_dialog_content = "Nawoxel... Kamu ini hebat sekawi, ya!",
  ui_story_5008_50081501_45_dialog_content = "Aku juga mau coba mendaur ulang beberapa sampah yang baru saja kita bersihkan agar bisa digunakan...",
  ui_story_5008_50081501_46_dialog_content = "Aku bisa memanfaatkan beberapa keahlian yang kupelajari di Illumina.",
  ui_story_5008_50081501_47_dialog_content = "Kelihatannya semua orang sudah siap bekerja... Termasuk Dove.",
  ui_story_5008_50081501_48_dialog_content = "Bagaimana kalau kuberi kalian Union Snack sebagai hadiah?",
  ui_story_5008_50081501_49_dialog_content = "<size=50>T-tidak, terima kasih!!!</size>",
  ui_story_5008_50081601_1_dialog_content = "Coo! Pola yang bercahaya ini... Rasanya aku kok pernah melihatnya, ya. Sepeertinya tidak asing...",
  ui_story_5008_50081601_2_dialog_content = "Oh! Ini semacam powa di kantow cabang Iwumina, ya?",
  ui_story_5008_50081601_3_dialog_content = "Aku bewum pewnah wihat yang sepewti ini di kantow cabang Northwand!",
  ui_story_5008_50081601_4_dialog_content = "Ini bukan pola Illumina... Coba kulihat...",
  ui_story_5008_50081601_5_dialog_content = "Coo! Ini dari Colossus!",
  ui_story_5008_50081601_6_dialog_content = "Ini persis dengan yang ada di Colossus!",
  ui_story_5008_50081601_7_dialog_content = "Tapi, ini tidak terhubung dengan sirkuit apa pun. Entah kenapa bisa bersinar.",
  ui_story_5008_50081601_8_dialog_content = "Bewawti... benda ini bewsinaw sendiwi?",
  ui_story_5008_50081601_9_dialog_content = "Tidak mau... lepas.",
  ui_story_5008_50081601_10_dialog_content = "Tidak tewjadi apa-apa waktu kutusuk.",
  ui_story_5008_50081601_11_dialog_content = "Coo... Kurasa bukan polanya yang membuatnya bersinar.",
  ui_story_5008_50081601_12_dialog_content = "Penyebabnya adalah bahan yang digunakan untuk menggambarnya berisi semacam zat yang bercahaya!",
  ui_story_5008_50081601_13_dialog_content = "Jadi, mereka menggunakan material yang mengandung zat pemancar cahaya untuk mendirikan kantor pos... dan Colossus?",
  ui_story_5008_50081601_14_dialog_content = "Itu sebabnya tempat ini bersinar?",
  ui_story_5008_50081601_15_dialog_content = "Aku juga tidak yakin...",
  ui_story_5008_50081601_16_dialog_content = "Tapi, kamu jadi kewihatan sangat kewen kawau bewsikap sewius begitu!",
  ui_story_5008_50081601_17_dialog_content = "Tiba-tiba aku jadi mewasakan kehebatan Iwumina gawa-gawa mewihatmu bawusan. Bangga sekawi deh wasanya!",
  ui_story_5008_50081601_18_dialog_content = "Ini tidak terbentuk secara alami.",
  ui_story_5008_50081601_19_dialog_content = "Bahan yang bersinar di pola itu pasti dibuat dengan teknologi unik Caelestite.",
  ui_story_5008_50081601_20_dialog_content = "Tapi, sepertinya tak ada yang tahu kenapa bisa bersinar.",
  ui_story_5008_50081601_21_dialog_content = "Begitu, ya... Pantas saja aku hanya melihatnya di Colossus dan di sini.",
  ui_story_5008_50081601_22_dialog_content = "Baikwah! Teka-tekinya sudah tewpecahkan!",
  ui_story_5008_50081601_23_dialog_content = "Ayo kita gambawi!",
  ui_story_5008_50081601_24_dialog_content = "Tempat ini kosong sekawi! Kita hawus mengisinya dengan sentuhan hawi waya!",
  ui_story_5008_50081601_25_dialog_content = "Coo... Aku tak mau menggambar apa pun, ah...",
  ui_story_5008_50081601_26_dialog_content = "Kamu takut aku bakaw menewtawakan gambawmu, ya?",
  ui_story_5008_50081601_27_dialog_content = "Tenang saja, Dove! Aku saja tidak menewtawakan gambaw buatan Vice, kok!",
  ui_story_5008_50081601_28_dialog_content = "Heh! Berani-beraninya kau membandingkan kemampuan menggambarku dengan Vice! Coo, coo!",
  ui_story_5008_50081601_29_dialog_content = "Bewawti kamu webih pintaw menggambaw ketimbang Vice?",
  ui_story_5008_50081601_30_dialog_content = "Jelas, dong!",
  ui_story_5008_50081701_1_dialog_content = "Kotak surat mandiri ini seperti bagian dari Colossus.",
  ui_story_5008_50081701_2_dialog_content = "Ah, kotak suwat! Aku jadi ingin mengiwim kawtu pos untuk diwi sendiwi!",
  ui_story_5008_50081701_3_dialog_content = "Aku bewum pewnah menewima kawtu pos Ewaveil!",
  ui_story_5008_50081701_4_dialog_content = "Kawau begitu, aku juga akan mengiwim satu, deh... Coo.",
  ui_story_5008_50081701_5_dialog_content = "Apa yang mau kautulis di kartu pos?",
  ui_story_5008_50081701_6_dialog_content = "Aku mau menulis \"Menghabiskan cuti berbayar sehari dengan tidur tak pernah sia-sia!\"",
  ui_story_5008_50081701_7_dialog_content = "Coo... Sudah.",
  ui_story_5008_50081701_8_dialog_content = "Aduh, menuwis apa, ya?",
  ui_story_5008_50081701_9_dialog_content = "Semoga aku bisa jadi owang yang pintaw dan cantik sepewti Nawoxel!",
  ui_story_5008_50081701_10_dialog_content = "Kau... salah tulis.",
  ui_story_5008_50081701_12_dialog_content = "Kata \"pintar\" tidak pakai huruf \"w\".",
  ui_story_5008_50081701_13_dialog_content = "Oh, biaw kuhapus huwuf \"w\"-nya... Sudah!",
  ui_story_5008_50081701_14_dialog_content = "Kantow pos ini akan kembawi bewopewasi setewah PlayerName kemawi dan menandatangani kontwak.",
  ui_story_5008_50081701_15_dialog_content = "Lalu, begitu kembawi ke Cwoud Mountain, aku akan menewima kawtu pos dawi Ewaveil!",
  ui_story_5008_50081701_16_dialog_content = "Yah, sewama kawtu posku tidak dikiwim oleh kuwiw sepewti Dove, sih.",
  ui_story_5008_50081701_17_dialog_content = "Coo, coo!?",
  ui_story_5008_50081701_18_dialog_content = "Kenapa kau tiba-tiba jongkok begitu, sih?",
  ui_story_5008_50081701_19_dialog_content = "Aku mau wihat bewapa banyak suwat yang bewum tewkiwim di kotak suwat ini!",
  ui_story_5008_50081701_20_dialog_content = "Itu masuk akal. Aku juga mau lihat, ah.",
  ui_story_5008_50081701_21_dialog_content = "Dove, sewimutmu menutupi segawanya!",
  ui_story_5008_50081701_22_dialog_content = "Sepertinya ada banyak surat yang belum terkirim...",
  ui_story_5008_50081701_23_dialog_content = "Sayang sekali. Kira-kira siapa kurir yang akan ditugaskan untuk mengirimnya, ya...?",
  ui_story_5008_50081701_24_dialog_content = "Untung bukan aku.",
  ui_story_5008_50081701_25_dialog_content = "Eh, wihat! Ada bunga sakuwa di sewuwuh pewmukaannya! Apa ini suwat ke Cwoud Mountain?",
  ui_story_5008_50081701_26_dialog_content = "Itu bunga sakura? Warnanya merah, jumlah kelopaknya ganjil...",
  ui_story_5008_50081701_27_dialog_content = "Apa yang sedang kalian berdua lakukan di depan kotak surat itu?",
  ui_story_5008_50081701_28_dialog_content = "Oh! Nawoxel! Aku hanya sedang mewihat kotak suwat dan menemukan suwat ke Cwoud Mountain!",
  ui_story_5008_50081701_29_dialog_content = "Cloud Mountain? Jadi, Eraveil sudah berhubungan dengan Cloud Mountain sejak dulu? Tapi, tidak ada kartu pos Cloud Mountain tadi...",
  ui_story_5008_50081701_30_dialog_content = "Aku ingin bertanya. Kalian—",
  ui_story_5008_50081701_31_dialog_content = "<size=45>Ah!!!</size>",
  ui_story_5008_50081701_32_dialog_content = "<size=45>Oh!</size>",
  ui_story_5008_50081701_33_dialog_content = "Prrppp... Kau baik-baik saja, Tweety? Naroxel?",
  ui_story_5008_50081701_34_dialog_content = "Oh... Aku tidak apa-apa... Aku hanya terkejut karena kau tiba-tiba berdiri...",
  ui_story_5008_50081701_35_dialog_content = "Aku tak menyangka kau tiba-tiba menunduk begitu... Aduh...",
  ui_story_5008_50081701_36_dialog_content = "Tweety? Tweety?",
  ui_story_5008_50081701_37_dialog_content = "<anim type=Shake>Wow... Aku mewihat tiga Dove dan empat Nawoxel...</anim>",
  ui_story_5008_50081801_1_dialog_content = "Hahaha...",
  ui_story_5008_50081801_2_dialog_content = "Nawoxel tewtawa!",
  ui_story_5008_50081801_3_dialog_content = "Tewtawa tewbahak-bahak!",
  ui_story_5008_50081801_4_dialog_content = "Ya, Tweety. Lihat ini.",
  ui_story_5008_50081801_5_dialog_content = "Hah? Sejak kapan patung keciw ini pakai topi?",
  ui_story_5008_50081801_6_dialog_content = "Haha... Apalagi topinya berbentuk kerucut, berwarna hitam, dan lucu...",
  ui_story_5008_50081801_7_dialog_content = "Benar-benar tidak cocok dengan patung itu.",
  ui_story_5008_50081801_8_dialog_content = "Nah, sekarang Colossus kecil ini sudah kelihatan manis.",
  ui_story_5008_50081801_9_dialog_content = "Cowossus butuh makan atau tidak, sih?",
  ui_story_5008_50081801_10_dialog_content = "Entahlah, tapi aku belum pernah melihat Soroz makan.",
  ui_story_5008_50081801_11_dialog_content = "Karena tidak bisa berkomunikasi dengannya, aku tak pernah bertanya apa dia butuh makan...",
  ui_story_5008_50081801_12_dialog_content = "Apa mungkin sebenawnya Cowossus butuh makan, tapi kita hanya tidak mewihatnya, ya?",
  ui_story_5008_50081801_13_dialog_content = "Ah! Atau jangan-jangan Sowoz sedang diet!",
  ui_story_5008_50081801_14_dialog_content = "Ada banyak gadis di Cwoud Mountain yang suka diet!",
  ui_story_5008_50081801_15_dialog_content = "Anu... Sepertinya Colossus tidak begitu...",
  ui_story_5008_50081801_16_dialog_content = "Kita tawuh bebewapa kudapan di dekat patung itu, yuk!",
  ui_story_5008_50081801_17_dialog_content = "Bagaimana kawau tewnyata Cowossus butuh makan?",
  ui_story_5008_50081801_18_dialog_content = "Dengan begitu...",
  ui_story_5008_50081801_19_dialog_content = "PlayerName bakaw tahu bahwa kita sudah menawuh bebewapa makanan di dekat patung Cowossus itu kawau dia datang nanti...",
  ui_story_5008_50081801_20_dialog_content = "Dia pasti bakaw senang!",
  ui_story_5008_50081801_21_dialog_content = "Baiklah, ayo kita coba saja.",
  ui_story_5008_50081801_22_dialog_content = "Nawoxel juga bewpikiw begitu? Asyik!",
  ui_story_5008_50081801_23_dialog_content = "Kita pakai saja Union Snack yang ini.",
  ui_story_5008_50081801_24_dialog_content = "Yang ini rasa oli.",
  ui_story_5008_50081801_25_dialog_content = "Patung yang malang...",
  ui_story_5008_50081801_26_dialog_content = "Bagus, itu cocok sekawi!",
  ui_story_5008_50081801_27_dialog_content = "Oh! Nawoxel, Dove! Masih ada yang kuwang!",
  ui_story_5008_50081801_28_dialog_content = "Sepewtinya aku punya topi yang webih cocok dawipada yang dikenakannya sekawang!",
  ui_story_5008_50081801_29_dialog_content = "Memangnya ada topi yang lebih cocok daripada yang kerucut ini?",
  ui_story_5008_50081801_30_dialog_content = "Topi macam apa itu?",
  ui_story_5008_50081801_31_dialog_content = "Ta-wa! Ini koweksi pwibadiku—",
  ui_story_5008_50081801_32_dialog_content = "Topi mandi!",
  ui_story_5008_50081801_33_dialog_content = "Oh... baiklah...",
  ui_story_5008_50081801_34_dialog_content = "Nah, Dove, apa masih ada bagian yang perlu dihias?",
  ui_story_5008_50081801_35_dialog_content = "Biar kuperiksa lagi material yang sudah terkumpul.",
  ui_story_5008_50081801_36_dialog_content = "Aku ingat tadi ada beberapa lilin kecil di sini. Sini, kubantu mencarinya.",
  ui_story_5008_50081801_37_dialog_content = "Nawoxel! Dove! Jangan tinggawkan aku, dong!",
  ui_story_5008_50081801_38_dialog_content = "Kita coba duwu topi mandi ini!",
  ui_story_5008_50081801_39_dialog_content = "Sepewtinya ini cocok dengan patung keciw itu!",
  ui_story_5008_50081901_A1_dialog_content = "<color=#e8d9bb>♪</color>",
  ui_story_5008_50081901_1_dialog_content = "Nawoxel, suawamu bagus sekawi...",
  ui_story_5008_50081901_2_dialog_content = "Terima kasih, Tweety.",
  ui_story_5008_50081901_3_dialog_content = "Yang bawusan wagu apa, sih? Ajawi aku, dong.",
  ui_story_5008_50081901_4_dialog_content = "Coo, lagunya bagus sekali.",
  ui_story_5008_50081901_5_dialog_content = "Sini, biar kuajari, Tweety. Aku sudah mencatatnya!",
  ui_story_5008_50081901_6_dialog_content = "<size=45><anim type=Shake>Coo, coo... Coo, coo, coo, coo! Coo, coo, coo, coo, coo!</anim></size>",
  ui_story_5008_50081901_7_dialog_content = "Dove, kamu... menyanyi?",
  ui_story_5008_50081901_8_dialog_content = "Kamu tewdengaw sepewti sedang mengingau.",
  ui_story_5008_50081901_9_dialog_content = "Dengarkan saja nadanya! Abaikan liriknya!",
  ui_story_5008_50081901_10_dialog_content = "Sebenarnya, ini lagu yang kupelajari di hutan dulu.",
  ui_story_5008_50081901_11_dialog_content = "Akan kunyanyikan lagi untukmu, Tweety.",
  ui_story_5008_50081901_12_dialog_content = "Nawoxel...",
  ui_story_5008_50081901_13_dialog_content = "Saat kamu bewnyanyi, pawa Firefwy seowah-owah bewgoyang mengikuti iwama...",
  ui_story_5008_50081901_14_dialog_content = "Aku juga lihat... Apa mereka memahami lagumu?",
  ui_story_5008_50081901_15_dialog_content = "Bewawti Firefwy suka musik, ya?",
  ui_story_5008_50081901_16_dialog_content = "Aku juga mau coba, ah!",
  ui_story_5008_50081901_17_dialog_content = "<size=45><anim type=Shake>Wawa, wawawa! Wawawa, wawa!</anim></size>",
  ui_story_5008_50081901_18_dialog_content = "Bergerak sedikit pun tidak.",
  ui_story_5008_50081901_19_dialog_content = "Hah? Meweka juga diam saja saat Dove menyanyi bawusan.",
  ui_story_5008_50081901_20_dialog_content = "Mungkin... meweka mewasa nyanyian kita tewdengaw bising.",
  ui_story_5008_50081901_21_dialog_content = "Jadi, hanya suawa Nawoxel saja yang dianggap sebagai nyanyian oweh pawa Firefwy?",
  ui_story_5008_50081901_22_dialog_content = "Sayangnya, kurasa memang begitu...",
  ui_story_5008_50081901_23_dialog_content = "Firefly di Colossus mampu berkomunikasi dengan kita dengan cara sederhana, tapi yang di sini sepertinya tidak bisa.",
  ui_story_5008_50081901_24_dialog_content = "Tapi, mereka bergoyang mengikuti irama laguku... Berarti, mereka bukan sekedar mesin.",
  ui_story_5008_50081901_25_dialog_content = "Firefly memang makhluk alam yang mengagumkan, ya?",
  ui_story_5008_50081901_26_dialog_content = "Mungkinkah mereka itu mahakarya ajaib Eraveil?",
  ui_story_5008_50081901_27_dialog_content = "Coba saja tanyakan pada PlayerName saat dia kembali nanti.",
  ui_story_5008_50081901_28_dialog_content = "Apa Firefly di Colossus juga bisa menari mengikuti laguku, ya...?",
  ui_story_5008_50082001_1_dialog_content = "Ewaveil tampak sangat indah dawi sini...",
  ui_story_5008_50082001_2_dialog_content = "Tapi, untuk apa pagaw keciw ini?",
  ui_story_5008_50082001_3_dialog_content = "Kita wihat pemandangan indah ini dengan webih cewmat, yuk.",
  ui_story_5008_50082001_4_dialog_content = "Kelihatannya jendela ini tertutup, tapi embusan anginnya masih bisa terasa.",
  ui_story_5008_50082001_5_dialog_content = "Berarti, jendela ini bisa dibuka.",
  ui_story_5008_50082001_6_dialog_content = "Karena itu, pagar ini dibuat agar tidak ada orang yang jatuh dari jendela.",
  ui_story_5008_50082001_7_dialog_content = "Coo! Kalau dilihat dari atas sini, tempat ini benar-benar terlihat tinggi...",
  ui_story_5008_50082001_8_dialog_content = "Lagi pula, kantor pos ini memang terletak di White Tower.",
  ui_story_5008_50082001_9_dialog_content = "Kudengar beberapa Aurorian takut pada ketinggian...",
  ui_story_5008_50082001_10_dialog_content = "Hah? Yang benaw?!",
  ui_story_5008_50082001_11_dialog_content = "Mana ada kuwiw yang takut pada ketinggian?",
  ui_story_5008_50082001_12_dialog_content = "Menurutku rasa takut pada ketinggian bukan masalah bagi kurir.",
  ui_story_5008_50082001_13_dialog_content = "Orang-orang 'kan tidak mengantre untuk mencari pekerjaan yang melelahkan... Coo...",
  ui_story_5008_50082001_14_dialog_content = "Biasanya, Union akan menguji para kandidat lebih dulu sebelum mereka secara resmi diangkat menjadi kurir.",
  ui_story_5008_50082001_15_dialog_content = "Coo? Jadi, orang yang takut pada ketinggian tidak akan lulus ujian?",
  ui_story_5008_50082001_16_dialog_content = "Kawau begitu, meweka tidak bisa jadi kuwiw?",
  ui_story_5008_50082001_17_dialog_content = "Benar. Union juga harus melindungi keamanan setiap kurir.",
  ui_story_5008_50082001_18_dialog_content = "Memang takut pada ketinggian itu seperti apa, sih?",
  ui_story_5008_50082001_19_dialog_content = "Kalau berdiri di tempat yang tinggi, awalnya kau merasa pusing, lalu pingsan.",
  ui_story_5008_50082001_20_dialog_content = "Begitu, ya... Coo...",
  ui_story_5008_50082001_21_dialog_content = "Dove? Dove?",
  ui_story_5008_50082001_22_dialog_content = "Nawoxel, Dove pingsan!",
  ui_story_5008_50082001_23_dialog_content = "Sayang sekali...",
  ui_story_5008_50082001_24_dialog_content = "Dove, tadi kau pingsan selama dua menit.",
  ui_story_5008_50082001_25_dialog_content = "Setelah kembali ke Illumina nanti, gajimu akan dipotong karena pingsan dua menit, ya.",
  ui_story_5008_50082001_26_dialog_content = "Coo!? Kenapa kamu tega sekali, sih!?",
  ui_story_5008_50082001_27_dialog_content = "Aku tahu kau tidak takut pada ketinggian, Dove.",
  ui_story_5008_50082001_28_dialog_content = "Kau selalu tertidur saat terbang, dan sering kali jatuh dari langit...",
  ui_story_5008_50082001_29_dialog_content = "Meskipun dari tempat sejauh ini pun aku sudah banyak mendengar soal perbuatanmu di Illumina.",
  ui_story_5008_50082001_30_dialog_content = "Coo...",
  ui_story_5008_50082101_1_dialog_content = "<size=45>Coo... Coo—hatsyiii!</size>",
  ui_story_5008_50082101_2_dialog_content = "Dove! Kamu sudah puwang!",
  ui_story_5008_50082101_3_dialog_content = "Ah... Kamu basah kuyup!",
  ui_story_5008_50082101_4_dialog_content = "Nih, pakai sawung tanganku!",
  ui_story_5008_50082101_5_dialog_content = "Tidak, tidak... Ikan, ikan, ikan...",
  ui_story_5008_50082101_6_dialog_content = "Tunggu sebentaw!",
  ui_story_5008_50082101_7_dialog_content = "Aku menawuh ikannya di akuawium... makanannya juga sudah kumasukkan!",
  ui_story_5008_50082101_8_dialog_content = "Sepewtinya meweka suka di sini.",
  ui_story_5008_50082101_9_dialog_content = "Benaw! Sekawang ikan-ikan keciw ini tampak sangat gembiwa!",
  ui_story_5008_50082101_10_dialog_content = "Bagaimana, Dove? Sudah mendingan? Masih kedinginan?",
  ui_story_5008_50082101_11_dialog_content = "<size=45>Coo—hatsyiii!</size>",
  ui_story_5008_50082101_12_dialog_content = "Dove, sudah waktunya kamu pulang dan melapor.",
  ui_story_5008_50082101_13_dialog_content = "Aku sudah meminta konvoi untuk menjemputmu di kantor pos terdekat.",
  ui_story_5008_50082101_14_dialog_content = "Coo? Sudah... selesai?",
  ui_story_5008_50082101_15_dialog_content = "Tapi, PlayerName belum menandatanganinya, coo...",
  ui_story_5008_50082101_16_dialog_content = "Apakah ini dianggap sebagai menyelesaikan pekerjaan saya di sini?",
  ui_story_5008_50082101_17_dialog_content = "Maksudku, kantor pos ini juga belum mengirim surat sungguhan satu pun...",
  ui_story_5008_50082101_18_dialog_content = "Tapi, kau 'kan sedang sakit. Tidak apa-apa, Dove.",
  ui_story_5008_50082101_19_dialog_content = "Kembali dan istirahat. Saya akan menjelaskan situasinya kepada Chief Vivian.",
  ui_story_5008_50082101_20_dialog_content = "Bagaimana kalau kumintakan dua minggu cuti berbayar?",
  ui_story_5008_50082101_21_dialog_content = "Ini memang pekerjaan yang berat untukmu.",
  ui_story_5008_50082101_22_dialog_content = "Sungguh? <size=45>Coo—hatsyiii!</size>",
  ui_story_5008_50082101_23_dialog_content = "Aku boleh pulang dan tidur sekarang?",
  ui_story_5008_50082101_24_dialog_content = "Tentu saja.",
  ui_story_5008_50082101_25_dialog_content = "Atas nama Courier Union, kuucapkan terima kasih atas usahamu, Dove.",
  ui_story_5008_50082101_26_dialog_content = "Dove, kapan-kapan bowehkah aku datang ke kantow cabang Iwumina dan main denganmu?",
  ui_story_5008_50082101_27_dialog_content = "Coo, tentu saja boleh.",
  ui_story_5008_50082101_28_dialog_content = "Asalkan aku sedang tidak sibuk dan tidak tidur, ya.",
  ui_story_5008_50082101_29_dialog_content = "Ah? Kawau begitu, aku tak akan pewnah bisa bewtemu Dove wagi?",
  ui_story_5008_50082101_30_dialog_content = "Coo, kau bisa membantuku mengantar surat!",
  ui_story_5008_50082101_31_dialog_content = "Dove, kewihatannya kamu sudah baikan sekawang! Kamu sudah tidak bewsin-bewsin!",
  ui_story_5008_50082101_32_dialog_content = "Coo!? Coo—hatysiii! Coo—hatysiii! Coo—hatysiii! Coo—hatysiii!",
  ui_story_5008_50082101_33_dialog_content = "Kalau begitu, aku pergi dulu! Anu... Sampai jumpa lagi... Teman-teman!",
  ui_story_5008_50082101_34_dialog_content = "Aku akan segewa datang untuk main bewsama, Dove!",
  ui_story_5008_50082101_35_dialog_content = "Semoga berhasil dalam segala hal, Dove. Alam akan menjagamu.",
  ui_story_5008_50082201_1_dialog_content = "Oh! Nawoxel, anak kucingnya dapat mainan bawu!",
  ui_story_5008_50082201_2_dialog_content = "Ini topi kurir surat.",
  ui_story_5008_50082201_3_dialog_content = "Sepewtinya kucing keciw ini suka topinya!",
  ui_story_5008_50082201_4_dialog_content = "Pasti topi ini milik anggota konvoi yang tertinggal.",
  ui_story_5008_50082201_5_dialog_content = "Lihat, ada logo Illumina yang sudah memudar di situ.",
  ui_story_5008_50082201_6_dialog_content = "Oh, iya... Kamu benaw!",
  ui_story_5008_50082201_7_dialog_content = "Dia menggosokkan kepawanya pada topi itu! Aduh, manis sekawi pus ini!",
  ui_story_5008_50082201_8_dialog_content = "Tiba-tiba dia mengeong...",
  ui_story_5008_50082201_9_dialog_content = "Dia mau apa, ya...?",
  ui_story_5008_50082201_10_dialog_content = "Hah? Kucing mengeong kawena ingin, 'kan?",
  ui_story_5008_50082201_11_dialog_content = "Tidak, Tweety.",
  ui_story_5008_50082201_12_dialog_content = "Kalau kucing mengeong, sebenawnya dia ingin memberitahumu apa yang diinginkannya.",
  ui_story_5008_50082201_13_dialog_content = "Saat ini...",
  ui_story_5008_50082201_14_dialog_content = "Aku tahu! Pus ini memandangi akuawium dawi tadi... Pasti dia ingin makan ikan!",
  ui_story_5008_50082201_15_dialog_content = "Jangan makan ikan ini, pus.",
  ui_story_5008_50082201_16_dialog_content = "Dove sudah bewusaha kewas menangkapnya!",
  ui_story_5008_50082201_17_dialog_content = "Jangan khawatir, Tweety.",
  ui_story_5008_50082201_18_dialog_content = "Dia tidak bakal memakan ikan itu. Aku bisa merasakannya.",
  ui_story_5008_50082201_19_dialog_content = "Dia hanya ingin bermain sebentar dengan ikan-ikan kecil ini...",
  ui_story_5008_50082201_20_dialog_content = "Dia bingung kenapa tidak bisa menyentuh mereka, padahal jaraknya sangat dekat.",
  ui_story_5008_50082201_21_dialog_content = "Oh? Sekawang aku paham!",
  ui_story_5008_50082201_22_dialog_content = "Oh, iya! Nawoxel, kita punya Union Snack yang baunya sepewti ikan asin, 'kan?",
  ui_story_5008_50082201_23_dialog_content = "Bagaimana kawau kita bewikan bebewapa pada pus ini?",
  ui_story_5008_50082201_24_dialog_content = "Baiklah... Ayo kita beri dia sedikit. Siapa tahu dia suka.",
  ui_story_5008_50082201_25_dialog_content = "Jangan langsung menyodorkannya. Taruh saja di atas lantai. Nanti dia akan mendekatinya sendiri kalau tertarik.",
  ui_story_5008_50082201_26_dialog_content = "Pus itu mewompat tuwun dawi wanjang mungiwnya!",
  ui_story_5008_50082201_27_dialog_content = "Pus itu menewkam kudapannya!",
  ui_story_5008_50082201_28_dialog_content = "Pus itu mengendus-endus!",
  ui_story_5008_50082201_29_dialog_content = "Aduh! Dia wangsung webah!",
  ui_story_5008_50082201_30_dialog_content = "Hmm... Dia tidak apa-apa, kok. Baunya terlalu menusuk hidungnya.",
  ui_story_5008_50082201_31_dialog_content = "Tewwawu menusuk hidung? Aku bewum pewnah coba wasa ini, sih... Sini, biaw kucicipi—",
  ui_story_5008_50082201_32_dialog_content = "Tweety, kalau kucing itu saja tidak tahan pada baunya, sebaiknya kau tidak—",
  ui_story_5008_50082201_33_dialog_content = "Yap... Baunya tewwawu... menusuk hidung...",
  ui_story_5008_50082301_1_dialog_content = "Kita memang hebat!",
  ui_story_5008_50082301_2_dialog_content = "Fiuh... Tempat ini sudah dihias dan seowah-owah kewihatan bawu!",
  ui_story_5008_50082301_3_dialog_content = "Hanya tinggal satu hal lagi...",
  ui_story_5008_50082301_4_dialog_content = "Ini dia. Ayo kita pasang lampu gantungnya.",
  ui_story_5008_50082301_5_dialog_content = "Baikwah!",
  ui_story_5008_50082301_6_dialog_content = "Apa ini... anak ayam keciw yang gemuk?",
  ui_story_5008_50082301_7_dialog_content = "Mungkin bukan. Ekownya panjang sekawi...",
  ui_story_5008_50082301_8_dialog_content = "Ini bukan burung, tapi perwakilan Colossus milik PlayerName.",
  ui_story_5008_50082301_9_dialog_content = "Tapi... kewihatannya kok jauh webih tewang dawi Cowossus-nya!",
  ui_story_5008_50082301_10_dialog_content = "Nah, kucing itu baru saja memberitahuku bahwa ini sebenarnya adalah gaya dalam perayaan Windelion.",
  ui_story_5008_50082301_11_dialog_content = "Wow! Dekowasinya juga bagian dawi kebiasaan festivaw Caewestite?",
  ui_story_5008_50082301_12_dialog_content = "Ya, dekorasi semacam ini disebut patung angin.",
  ui_story_5008_50082301_13_dialog_content = "Tadi aku melihat struktur umum dari patung angin ini ditampilkan di belakang cetak biru desainnya.",
  ui_story_5008_50082301_14_dialog_content = "Tapi, saat pertama kali melihatnya, aku tidak tahu bahwa itu adalah dekorasi Windelion... Tadinya kupikir itu cuma peralatan biasa.",
  ui_story_5008_50082301_15_dialog_content = "Untungnya, kucing itu memberitahuku.",
  ui_story_5008_50082301_16_dialog_content = "Tapi, proses pembuatan patung angin ini tidak tertulis pada cetak biru.",
  ui_story_5008_50082301_17_dialog_content = "Jadi, kurasa benda yang kita gantung barusan... memang seharusnya dipasang seperti itu.",
  ui_story_5008_50082301_18_dialog_content = "Mungkin kelihatannya memang tidak sempurna... tapi aku sudah berusaha semampuku. Semoga PlayerName tidak keberatan.",
  ui_story_5008_50082301_19_dialog_content = "Menuwutku bagus, kok!",
  ui_story_5008_50082301_20_dialog_content = "Kiwa-kiwa akan begini nanti kawau PlayerName masuk!",
  ui_story_5008_50082301_21_dialog_content = "Aku akan membuka pintu, kemudian PlayerName masuk, bangun, lihat boneka windewion...",
  ui_story_5008_50082301_22_dialog_content = "Hmm...",
  ui_story_5008_50082301_23_dialog_content = "Ada apa, Tweety? Apa kita salah memasangnya?",
  ui_story_5008_50082301_24_dialog_content = "Yah... Posisinya pas, tapi menuwutku patung angin ini agak kekeciwan!",
  ui_story_5008_50082301_25_dialog_content = "Ukuwannya keciw sekawi... jadi kuwang mengagumkan.",
  ui_story_5008_50082301_26_dialog_content = "Begitu rupanya... Ini memang bukan kejutan besar, sih.",
  ui_story_5008_50082301_27_dialog_content = "Nawoxel, bagaimana kawau kita membuat patung angin yang webih besaw?",
  ui_story_5008_50082301_28_dialog_content = "Hmm... Kita bisa menawuh banyak Union Snack di dalam patung angin ini!",
  ui_story_5008_50082301_29_dialog_content = "Oh! Wawu kita juga bisa menuwiskan pesan untuknya!",
  ui_story_5008_50082301_30_dialog_content = "Wawu aku akan sembunyi di wampu itu...",
  ui_story_5008_50082301_31_dialog_content = "Sesegera PlayerName masuk, aku akan melempar boneka windewion besar kita!",
  ui_story_5008_50082301_32_dialog_content = "Dengan begitu, PlayerName bisa melihat boneka kecil di ceiwing, dan makan makanan ringan di yang besar!",
  ui_story_5008_50082301_33_dialog_content = "Ya, dan membaca pesan kita.",
  ui_story_5008_50082301_34_dialog_content = "Terima kasih, Tweety. Idemu bagus sekali.",
  ui_story_5008_50082301_35_dialog_content = "Ayo kita mulai sekarang juga!",
  ui_story_5008_50082301_36_dialog_content = "Asyiiik!",
  ui_story_5008_50082301_37_dialog_content = "Fiuh... Akhiwnya, patung angin besaw kita jadi juga!",
  ui_story_5008_50082301_38_dialog_content = "Iya. Sulit sekali membuatnya...",
  ui_story_5008_50082301_39_dialog_content = "Nah, sekarang kita masukkan kudapan dan pesannya sekarang.",
  ui_story_5008_50082301_40_dialog_content = "Tweety, menurutmu apa rasa Union Snack yang akan disukai PlayerName?",
  ui_story_5008_50082301_41_dialog_content = "Aku sudah memeriksanya barusan. Yang kita punya hanya tinggal rasa Skunk Butt, Stinky Sulfur, dan Rusty Iron Blade.",
  ui_story_5008_50082301_42_dialog_content = "Oh, yang rasa Teppanyaki Strawberries dan Absolutely Fabulous juga masih ada beberapa, sih.",
  ui_story_5008_50082301_43_dialog_content = "Sepewtinya PlayerName tak bakaw memiwih wasa Teppanyaki Stwawbewwies!",
  ui_story_5008_50082301_44_dialog_content = "Kenapa begitu?",
  ui_story_5008_50082301_45_dialog_content = "Duwu, saat aku menjadi wesepsionis di Cwoud Mountain, kudengaw ada owang yang sebaya dengan PlayerName bewkata...",
  ui_story_5008_50082301_46_dialog_content = "\"Stwobewi itu hanya untuk owang-owang yang wemah dan manja!\"",
  ui_story_5008_50082301_47_dialog_content = "Jadi, kuwasa PlayerName juga akan bewpikiwan begitu...",
  ui_story_5008_50082301_48_dialog_content = "Masuk akal juga, sih...",
  ui_story_5008_50082301_49_dialog_content = "Kalau begitu, ayo kita makan saja yang rasa stroberi lalu kita masukkan keempat rasa lainnya ke dalam patung.",
  ui_story_5008_50082301_50_dialog_content = "Oh, iya! Wawu kita mau tuwis apa untuk pesannya?",
  ui_story_5008_50082301_51_dialog_content = "Apa pun boleh asal terdengar memberi semangat.",
  ui_story_5008_50082301_52_dialog_content = "Baikwah—siap!",
  ui_story_5008_50082301_53_dialog_content = "\"Semoga PlayerName sewawu sibuk kawena sibuk itu adawah haw pawing kewen di dunia!\"",
  ui_story_5008_50082301_54_dialog_content = "\"Semoga tangan, kepawa, dan badanmu makin besaw dan buwat!\"",
  ui_story_5008_50082301_55_dialog_content = "\"Semoga PlayerName bahagia—setiap hawi!\"",
  ui_story_5008_50082301_56_dialog_content = "Sewesai!",
  ui_story_5008_50082301_57_dialog_content = "\"Semoga alam selalu menjagamu, sekarang dan seterusnya.\"",
  ui_story_5008_50082301_58_dialog_content = "\"Setiap detik yang berlalu telah hilang dalam aliran waktu. Saat ini akan selalu menjadi kenangan yang paling indah.\"",
  ui_story_5008_50082301_59_dialog_content = "\"Tolong jangan mencari keabadian... Siklus alam yang tak terbatas telah memilih jalan untukmu.\"",
  ui_story_5008_50082301_60_dialog_content = "Kita masukkan pesannya, yuk.",
  ui_story_5008_50082301_61_dialog_content = "Biaw kuikat patung besaw itu dawi bewakang!",
  ui_story_5008_50082301_62_dialog_content = "Goyang, goyang! Goyang, goyang, goyang!",
  ui_story_5008_50082301_63_dialog_content = "Sewesai!",
  ui_story_5008_50082301_64_dialog_content = "Luar biasa. Bagus sekali, Tweety.",
  ui_story_5008_50082301_65_dialog_content = "Nah... Sekarang kita tinggal menunggu PlayerName datang.",
  ui_story_5008_50082301_66_dialog_content = "Aku sudah tak sabar ingin melihat wajahnya saat dia membuka pintu."
}
return config
